// Strict input validation. Nothing here silently drops a lead: every
// item leaves this node with valid=true or valid=false plus a reason,
// and the IF node below routes both outcomes to somewhere recorded.
const body = $json.body || {};

function isNonEmptyString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\+?[0-9()\-.\s]{7,20}$/;

const reasons = [];

// name: required, string, non-empty after trim, sane max length
if (!isNonEmptyString(body.name)) {
  reasons.push('name_missing_or_invalid_type');
} else if (body.name.trim().length > 200) {
  reasons.push('name_too_long');
}

// email: required, must be a string, must match a real email shape
if (typeof body.email !== 'string' || body.email.trim().length === 0) {
  reasons.push('email_missing_or_invalid_type');
} else if (!EMAIL_RE.test(body.email.trim())) {
  reasons.push('email_format_invalid');
}

// company: required, string, non-empty
if (!isNonEmptyString(body.company)) {
  reasons.push('company_missing_or_invalid_type');
} else if (body.company.trim().length > 200) {
  reasons.push('company_too_long');
}

// phone: optional, but if present must be a string matching a phone shape
if (body.phone !== undefined && body.phone !== null && body.phone !== '') {
  if (typeof body.phone !== 'string' || !PHONE_RE.test(body.phone.trim())) {
    reasons.push('phone_invalid_type_or_format');
  }
}

// message: optional, but if present must be a string within a sane length
if (body.message !== undefined && body.message !== null && body.message !== '') {
  if (typeof body.message !== 'string') {
    reasons.push('message_invalid_type');
  } else if (body.message.length > 5000) {
    reasons.push('message_too_long');
  }
}

// lead_id: required, string, non-empty -- the source system's own id,
// used as the idempotency/dedup key alongside email
if (!isNonEmptyString(body.lead_id)) {
  reasons.push('lead_id_missing_or_invalid_type');
}

const valid = reasons.length === 0;

return {
  json: {
    valid,
    reasons,
    lead_id: isNonEmptyString(body.lead_id) ? body.lead_id.trim() : null,
    name: isNonEmptyString(body.name) ? body.name.trim() : null,
    email: typeof body.email === 'string' ? body.email.trim().toLowerCase() : null,
    company: isNonEmptyString(body.company) ? body.company.trim() : null,
    phone: typeof body.phone === 'string' && body.phone.trim() ? body.phone.trim() : null,
    message: typeof body.message === 'string' ? body.message : null,
    received_at: new Date().toISOString()
  }
};

// Orchestrates enrichment then CRM upsert for one validated lead, with
// manual retry and exponential backoff on each external call. A
// persistent failure at either stage never drops the lead silently --
// it is returned with status='dead_lettered', the failing stage, and
// the last error, so the branch below records it as a dead-letter row.
const lead = $json;
const ENRICH_URL = $env.ENRICH_URL;
const CRM_URL = $env.CRM_URL;

async function withRetry(fn, maxAttempts, baseDelayMs) {
  let lastError = null;
  let attempts = 0;
  let delay = baseDelayMs;
  while (attempts < maxAttempts) {
    attempts += 1;
    try {
      const result = await fn();
      return { ok: true, result, attempts };
    } catch (err) {
      lastError = (err && err.message) ? err.message : String(err);
      if (attempts < maxAttempts) {
        await new Promise((resolve) => setTimeout(resolve, delay));
        delay *= 2; // exponential backoff: 200ms, 400ms, ...
      }
    }
  }
  return { ok: false, error: lastError, attempts };
}

const enrichRes = await withRetry(
  () => this.helpers.httpRequest({
    method: 'POST',
    url: `${ENRICH_URL}/enrich`,
    body: { email: lead.email, company: lead.company },
    json: true,
    timeout: 2000
  }),
  3,
  200
);

if (!enrichRes.ok) {
  return {
    json: {
      ...lead,
      status: 'dead_lettered',
      stage: 'enrichment',
      reason: enrichRes.error,
      attempts: enrichRes.attempts
    }
  };
}

const enrichment = enrichRes.result;

const crmRes = await withRetry(
  () => this.helpers.httpRequest({
    method: 'POST',
    url: `${CRM_URL}/contacts`,
    body: {
      email: lead.email,
      name: lead.name,
      company: lead.company,
      phone: lead.phone,
      message: lead.message,
      lead_id: lead.lead_id,
      enrichment
    },
    json: true,
    timeout: 2000
  }),
  3,
  200
);

if (!crmRes.ok) {
  return {
    json: {
      ...lead,
      enrichment,
      status: 'dead_lettered',
      stage: 'crm_upsert',
      reason: crmRes.error,
      attempts: crmRes.attempts
    }
  };
}

return {
  json: {
    ...lead,
    enrichment,
    crm_contact: crmRes.result && crmRes.result.contact,
    status: 'accepted'
  }
};
